select private.rc_release_guide(
  p_slug => 'underwriting-migrate-legacy-agreements',
  p_tool_key => 'underwriting',
  p_title => 'Migrate legacy agreements',
  p_summary => 'Load a manifest of existing agreements, import each one with its document as a draft contract, and review the results.',
  p_screen_keys => array['underwriting.migration'],
  p_sort_order => 90,
  p_version_note => 'New guide for the legacy-agreement migration',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Administrators use this screen to bring agreements from the station's legacy records into Underwriting & Traffic. Open it from the Contracts list: "},{"type":"text","text":"Migrate legacy agreements","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Load a manifest"}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest is a spreadsheet saved as CSV, one row per agreement. The first row names the columns. Every row needs the underwriter and the document's file name; the order number, run dates, sponsorship total, contract type, Drive file id, documentation status, and notes are optional. Name the batch and select "},{"type":"text","text":"Load manifest","marks":[{"type":"bold"}]},{"type":"text","text":". Rows that can't be read are listed by number and left out; the rest load."}]},{"type":"paragraph","content":[{"type":"text","text":"The underwriter must already be on file under the same name. Add any that are missing under Underwriters first."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"Documents","marks":[{"type":"bold"}]},{"type":"text","text":", choose every document the manifest names at once. Each entry is matched to its file by name, and any entry without a file is listed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":". Entries are read one at a time, the same way "},{"type":"text","text":"Create from the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" reads a single order. Keep the page open until the run finishes, or select "},{"type":"text","text":"Stop after this one","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest's facts win over what the document says; the schedule comes from the document. Each entry becomes a draft contract, which schedules nothing until someone activates it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review"}]},{"type":"paragraph","content":[{"type":"text","text":"The table lists every entry with its status. An imported entry links to its draft's schedule step and says how many lines were saved. "},{"type":"text","text":"To review","marks":[{"type":"bold"}]},{"type":"text","text":" lists what needs a person's eye: lines that couldn't be saved, and where the document disagrees with the manifest. A failed entry shows why; fix the cause and import again."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Running it again"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Importing again never creates a second contract for an entry that already has one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loading a corrected manifest updates entries that haven't been imported. Keep each row's key the same."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To redo an imported entry, delete its draft contract; the entry can then be imported again."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-29-underwriting-agreement-migration',
  p_tool_key => 'underwriting',
  p_released_on => '2026-09-29',
  p_title => 'Migrating legacy agreements',
  p_guide_slugs => array['underwriting-migrate-legacy-agreements'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Administrators can now bring existing agreements into Underwriting & Traffic in a batch. Load a manifest of the agreements, choose their documents, and each one is read into a draft contract the same way Create from the agreement reads a single order. The manifest's facts take precedence over the document, and running a batch again never duplicates a contract."}]}]}$body$
);
